begin;
-- Real existing account/session contexts, rollback-only; no passwords, token minting or new accounts.
do $$declare own uuid;student uuid;os uuid;ss uuid;gid uuid;dm uuid;msg bigint;othergrade uuid;invite jsonb;mail text;original_grade smallint;begin
 select owner_id into own from acc_private.owner_setup where id;select p.id into student from public.acc_profiles p where p.id<>own and p.role='student' and not p.suspended limit 1;
 select id into os from auth.sessions where user_id=own limit 1;select id into ss from auth.sessions where user_id=student limit 1;
 if own is null or student is null or os is null or ss is null then raise exception 'Two real active account sessions are required';end if;
 select grade into original_grade from acc_private.grades where person=student;update auth.users set raw_user_meta_data=raw_user_meta_data||jsonb_build_object('role','admin','grade',case when original_grade=9 then 12 else 9 end,'email_verified',true) where id=student;if (select grade from acc_private.grades where person=student) is distinct from original_grade or (select role from public.acc_profiles where id=student)<>'student' then raise exception 'Editable metadata escalated privileges';end if;
 perform set_config('acc_test.owner',own::text,true);perform set_config('acc_test.student',student::text,true);perform set_config('acc_test.os',os::text,true);perform set_config('acc_test.ss',ss::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 if not acc_private.is_owner() or not acc_private.can('reports') or not acc_private.can('ban') or not acc_private.can('announcements') then raise exception 'Owner permissions incomplete';end if;
 gid:=(public.acc_call('group','{"name":"Rollback launch security check"}')->>'room')::uuid;perform set_config('acc_test.group',gid::text,true);
 -- Isolate friend-consent checks without changing any saved relationship after rollback.
 delete from public.acc_friends where (sender=own and recipient=student) or(sender=student and recipient=own);
 begin perform public.acc_call('dm',jsonb_build_object('target',student));raise exception 'DM without consent';exception when others then if sqlerrm='DM without consent' then raise;end if;end;
 perform public.acc_call('friend',jsonb_build_object('target',student));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if acc_private.is_owner() or acc_private.can('announcements') then raise exception 'Student escalated';end if;
 begin perform public.acc_call('adminSnapshot');raise exception 'Student admin access';exception when others then if sqlerrm='Student admin access' then raise;end if;end;
 begin perform public.acc_call('messages',jsonb_build_object('room',gid));raise exception 'Private group exposed';exception when others then if sqlerrm='Private group exposed' then raise;end if;end;
 select room into othergrade from acc_private.channel_settings where grade is not null and grade<>(select grade from acc_private.grades where person=student) limit 1;
 if othergrade is null or acc_private.access(othergrade) then raise exception 'Grade check unavailable/failed';end if;
 begin perform public.acc_call('messages',jsonb_build_object('room',othergrade));raise exception 'Cross-grade read';exception when others then if sqlerrm='Cross-grade read' then raise;end if;end;
 begin perform public.acc_call('send',jsonb_build_object('room',(select id from public.acc_rooms where name='announcements' and kind='school' limit 1),'body','Rollback forbidden announcement','nonce',gen_random_uuid()));raise exception 'Student announcement';exception when others then if sqlerrm='Student announcement' then raise;end if;end;
 perform public.acc_call('friend',jsonb_build_object('target',own,'choice','accept'));
 dm:=(public.acc_call('dm',jsonb_build_object('target',own))->>'room')::uuid;
 update public.acc_profiles set last_post=null where id=student;
 perform public.acc_call('send',jsonb_build_object('room',dm,'body','Rollback-only launch security test','nonce',gen_random_uuid()));
 select max(id) into msg from public.acc_messages where room=dm and author=student;
 begin perform public.acc_call('send',jsonb_build_object('room',dm,'body','Rollback rapid message','nonce',gen_random_uuid()));raise exception 'Rate limit not enforced';exception when others then if sqlerrm='Rate limit not enforced' then raise;end if;end;
 perform public.acc_call('reaction',jsonb_build_object('message',msg,'emoji','👍'));
 perform public.acc_call('report',jsonb_build_object('message',msg,'reason','Rollback-only report workflow test'));
 perform public.acc_call('preference',jsonb_build_object('target',own,'blocked',true));
 update public.acc_profiles set last_post=null where id=student;
 begin perform public.acc_call('send',jsonb_build_object('room',dm,'body','Rollback blocked DM','nonce',gen_random_uuid()));raise exception 'Block bypass';exception when others then if sqlerrm='Block bypass' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 begin perform public.acc_call('invite',jsonb_build_object('room',gid,'target',student));raise exception 'Blocked invitation allowed';exception when others then if sqlerrm='Blocked invitation allowed' then raise;end if;end;
 delete from public.acc_preferences where (person=student and target=own) or(person=own and target=student);
 perform public.acc_call('invite',jsonb_build_object('room',gid,'target',student));
 update public.acc_profiles set last_post=null where id=own;perform public.acc_call('send',jsonb_build_object('room',dm,'body','Rollback-only reply check','reply',msg,'nonce',gen_random_uuid()));
 perform public.acc_call('deleteMessage',jsonb_build_object('message',msg));
 if exists(select 1 from public.acc_messages where id=msg and (body<>'' or not deleted)) then raise exception 'Deletion failed';end if;
 select email into mail from auth.users where id=student;invite:=public.acc_call('inviteModerator',jsonb_build_object('email',mail));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 perform public.acc_call('acceptModerator',jsonb_build_object('code',invite->>'code'));
 if not acc_private.can('reports') or acc_private.can('announcements') then raise exception 'Moderator defaults unsafe';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 perform public.acc_call('revokeModerator',jsonb_build_object('target',student));
 perform public.acc_call('suspend',jsonb_build_object('target',student,'enabled',true));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if acc_private.verified() then raise exception 'Suspension not immediate';end if;
end $$;
rollback;
select 'PASS two existing account/session database contexts: owner rights, student escalation denial, cross-grade/group privacy, friend consent/DM, send/rate limit/reaction/report/block, invitation block, group membership, deletion, moderator acceptance/revocation, suspension/session invalidation. All changes rolled back; this is not a WebSocket/browser login test.' result;
